function save(){captureUI();clearTimeout(saveTimer);saveTimer=setTimeout(()=>{const text=JSON.stringify(project);try{localStorage.setItem(KEY,text);sessionStorage.setItem(KEY,text);storageAvailable=true;$('#save-status').textContent='✓ Guardado en este navegador';}catch{storageAvailable=false;$('#save-status').textContent='⚠ Exporta tu proyecto para conservarlo';toast('El navegador no permite guardar o no tiene espacio. Descarga el proyecto.');}try{document.cookie='oteaSession='+encodeURIComponent(JSON.stringify(project.settings))+'; Path=/; SameSite=Lax; Secure';}catch{}},150);updateProgress();}
const FORM_IDS=['engine','ticks','seed','cooling','map-select','theme','speed','tournament-name','tournament-engine','pairing','swiss-rounds','match-rounds','tournament-ticks','win-points','draw-points','tie-rule','tournament-map','tournament-theme','simple-ticks','room-auto'];
function captureUI(){const values={};for(const id of FORM_IDS)values[id]=$('#'+id).value;project.uiState={values,arena:selectedTanks('#participants').map(t=>t.id),tournament:selectedTanks('#tournament-participants').map(t=>t.id)};if(standings.length)project.lastTournament={rows:standings,fixtures,meta:currentTournament};}
function restoreUI(){const ui=project.uiState;if(ui?.values)for(const id of FORM_IDS){const node=$('#'+id),value=ui.values[id];if(value===undefined||String(value).length>100)continue;if(node.tagName==='SELECT'&&![...node.options].some(o=>o.value===String(value)))continue;node.value=value;}participantList($('#participants'),$('#engine').value,ui?.arena);participantList($('#tournament-participants'),$('#tournament-engine').value,ui?.tournament);const last=project.lastTournament;if(last&&Array.isArray(last.rows)&&last.rows.length<=8&&last.rows.every(r=>typeof r.name==='string'&&['id','points','wins','draws','losses','buchholz','combat'].every(k=>Number.isFinite(r[k])))&&Array.isArray(last.fixtures)&&last.fixtures.length<200){standings=last.rows;fixtures=last.fixtures;currentTournament=last.meta;$('#league-title').textContent=currentTournament?.name||'Copa OTEA';standingsRender();}}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=el('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function go(view){if(combatView?.expanded&&view!=='arena')combatView.close();if(!['hangar','workshop','arena','missions','tournament','resources'].includes(view))view='hangar';currentView=view;document.querySelectorAll('.view').forEach(s=>s.hidden=s.id!==view);document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));history.replaceState(null,'','#'+view);if(view==='workshop')renderEditor();if(view==='arena')renderParticipants();if(view==='tournament'){renderTournamentParticipants();roomTanksRender();}if(view==='missions')renderMissions();window.scrollTo({top:0,behavior:'instant'});}
const javaUndo=new Map(),javaSelectionNotices=new Map();let javaRenameSession=null;
function renderJavaIdentity(){const t=tank(),box=$('#java-identity'),info=javaIdentity(t);box.hidden=!['java','blocks'].includes(t.language);if(box.hidden)return;$('#java-class-name').textContent=info?.className||'Sin reconocer';$('#java-package-name').textContent=info?(info.packageName||'(sin paquete)'):'—';$('#java-full-name').textContent=info?.fullName||'Declara public class Nombre para identificar el carro.';$('#java-identity-origin').textContent=t.language==='blocks'?'GENERADA DESDE BLOQUES':'LEÍDA DEL CÓDIGO';const peers=info?project.tanks.filter(v=>v!==t&&javaIdentity(v)?.fullName===info.fullName):[];const message=!info?'No se reconoce una única clase pública. Revisa su declaración y valida el código Java.':peers.length?'Comparte identidad con '+peers.map(v=>v.name).join(' · ')+'. Si participan juntos en Java, distingue una de sus identidades.':t.language==='blocks'?'La clase se genera del nombre del carro. Tus bloques se conservan.':'Cambiar el nombre visible del carro no cambia esta clase.';if($('#java-identity-status').textContent!==message)$('#java-identity-status').textContent=message;box.classList.toggle('identity-conflict',!!peers.length);$('#java-locate').disabled=!info;$('#java-distinguish').disabled=!info;const undo=javaUndo.get(t.id);$('#java-undo').hidden=!undo||t.code!==undo.after.code||t.name!==undo.after.name||t.language!==undo.after.language;}
function renderJavaSelection(container,engine){let notice=javaSelectionNotices.get(container);if(!notice){notice=el('div','java-selection-notice');notice.setAttribute('role','status');container.after(notice);javaSelectionNotices.set(container,notice);}const conflicts=engine==='jvm'?javaConflicts(selectedTanks('#'+container.id)):[];notice.hidden=!conflicts.length;notice.replaceChildren();if(!conflicts.length)return;notice.append(el('b','','Clases Java repetidas'),el('p','micro',conflicts.map(g=>g.fullName+' → '+g.tanks.map(t=>t.name).join(' · ')).join('\n')));const review=el('button','','Revisar clases');review.onclick=guard(()=>showJavaConflicts(conflicts));notice.append(review);}
async function showJavaConflicts(conflicts){if(combatView.expanded)await combatView.close();const list=$('#java-conflict-list');list.replaceChildren();for(const group of conflicts){const row=el('section','java-conflict-group');row.append(el('code','',group.fullName));for(const t of group.tanks){const item=el('div','java-conflict-row');item.append(el('span','',t.name+(t.creator?' · '+t.creator:'')));const local=project.tanks.find(v=>v.id===t.id);if(local){const button=el('button','','Revisar en taller');button.setAttribute('aria-label','Revisar '+t.name+' en el taller');button.onclick=()=>{$('#java-conflict-dialog').close();selected=local.id;go('workshop');$('#java-identity').scrollIntoView({block:'center',behavior:'instant'});$('#java-distinguish').focus({preventScroll:true});};item.append(button);}else item.append(el('small','','El creador debe distinguirlo y volver a inscribirlo en la sala.'));row.append(item);}list.append(row);}if(!$('#java-conflict-dialog').open)$('#java-conflict-dialog').showModal();}
function showIdentityPlan(){const session=javaRenameSession;if(!session)return;const {t,original}=session;let plan;try{plan=uniqueIdentityPlan({...t,...original},project.tanks.filter(v=>v!==t));if(t.language==='java'){const pkg=$('#java-package-edit').value.trim();if(!validPackage(pkg))throw Error('Escribe un paquete válido, por ejemplo aula.equipo2.');const code=changeJavaPackage(original.code,pkg);plan={...plan,code,after:inspectJava(code)};}if(project.tanks.some(v=>v!==t&&javaIdentity(v)?.fullName===plan.after.fullName))throw Error('Ese identificador ya lo utiliza otro carro del hangar. Elige un paquete distinto.');if(plan.after.fullName===plan.before.fullName)throw Error('La propuesta debe tener un identificador distinto del actual.');session.plan=plan;$('#java-rename-after').textContent=plan.after.fullName;$('#java-rename-diff').textContent=t.language==='blocks'?'Nombre del carro: '+original.name+' → '+plan.name+'\nClase: '+plan.before.fullName+' → '+plan.after.fullName+'\nLos bloques no se modifican.':'Código que se guardará:\n\n'+plan.code;$('#java-rename-feedback').textContent=t.language==='blocks'?'El nuevo nombre visible será '+plan.name+'.':'Se ajusta el paquete y las referencias explícitas a esta clase. Revisa los imports si usas otras clases de tu antiguo paquete. Valida Java después de aplicar.';$('#java-rename-apply').disabled=false;}catch(e){session.plan=null;$('#java-rename-after').textContent='Propuesta no válida';$('#java-rename-feedback').textContent=e.message;$('#java-rename-diff').textContent='';$('#java-rename-apply').disabled=true;}}
$('#java-locate').onclick=()=>{const t=tank(),info=javaIdentity(t);if(!info)return;if(t.language==='blocks'){const preview=$('.java-peek');preview.open=true;$('#java-preview').scrollIntoView({block:'start',behavior:'instant'});}else{const source=$('#source');source.focus();source.setSelectionRange(info.classStart,info.classEnd);source.scrollTop=Math.max(0,(info.line-3)*(parseFloat(getComputedStyle(source).lineHeight)||20));diagnostics('Clase '+info.className+' · línea '+info.line+' · '+info.fullName);}};
$('#java-distinguish').onclick=guard(()=>{if(running||jvmStarting||tournamentRunning)return toast('Detén la partida antes de cambiar la identidad Java.');const t=tank(),plan=uniqueIdentityPlan(t,project.tanks);javaRenameSession={t,original:{code:t.code,name:t.name,language:t.language},plan};$('#java-rename-before').textContent=plan.before.fullName;$('#java-rename-note').textContent=t.language==='blocks'?'Proponemos un nombre de carro que genere una clase distinta. Los bloques y su comportamiento se conservan.':'Proponemos un paquete distinto para conservar el nombre de la clase, sus constructores y las órdenes del carro. El alias visible se conserva. Puedes revisar el código antes de aplicar.';$('#java-package-edit-label').hidden=t.language!=='java';$('#java-package-edit').value=plan.after.packageName;showIdentityPlan();$('#java-rename-dialog').showModal();});
$('#java-package-edit').oninput=showIdentityPlan;
$('#java-rename-apply').onclick=guard(()=>{const session=javaRenameSession;if(!session?.plan)return;const {t,original}=session;if(!project.tanks.includes(t)||t.code!==original.code||t.name!==original.name||t.language!==original.language)throw Error('El carro ha cambiado. Cierra esta propuesta y prepara otra para conservar tus últimas ediciones.');if(running||jvmStarting||tournamentRunning)throw Error('Detén la partida antes de cambiar la identidad Java.');showIdentityPlan();if(!session.plan)return;const {plan}=session;Object.assign(t,{code:plan.code,name:plan.name});javaUndo.set(t.id,{before:original,after:{code:t.code,name:t.name,language:t.language}});$('#java-rename-dialog').close();javaRenameSession=null;renderEditor();save();toast('Identidad aplicada · '+plan.after.fullName+' · Puedes deshacer el cambio.');});
$('#java-undo').onclick=()=>{const t=tank(),undo=javaUndo.get(t.id);if(!undo||t.code!==undo.after.code||t.name!==undo.after.name||t.language!==undo.after.language)return;if(running||jvmStarting||tournamentRunning)return toast('Detén la partida antes de cambiar la identidad Java.');Object.assign(t,undo.before);javaUndo.delete(t.id);renderEditor();save();toast('Identidad anterior recuperada.');};
for(const id of ['java-rename-close','java-rename-cancel'])$('#'+id).onclick=()=>$('#java-rename-dialog').close();$('#java-rename-dialog').addEventListener('close',()=>javaRenameSession=null);
