function renderList(){const container=$('#tank-list');container.replaceChildren();for(const t of project.tanks){const b=el('button','tank-list-item'+(t.id===selected?' active':''));b.append(el('span','',t.name),el('small','',t.language==='blocks'?'▰':t.language==='java'?'JAVA':t.language==='python'?'PY':'JS'));b.onclick=()=>{selected=t.id;insertPath=[];renderEditor();};container.append(b);}}
function listAt(path){let list=tank().blocks[eventKey]||(tank().blocks[eventKey]=[]);for(const i of path){if(!list[i]?.children)return tank().blocks[eventKey];list=list[i].children;}return list;}
function renderBlocks(){tank().blocks[eventKey] ||= [];const target=$('#block-workspace');target.replaceChildren();let count=0;try{count=validateBlocks(tank().blocks);}catch{}const top=el('button','add-child','＋ Añadir al programa principal');top.onclick=()=>{insertPath=[];toast('Elige una pieza de la paleta.');};target.append(top);
 const render=(list,parent,path)=>{for(const [i,b] of list.entries()){const def=COMMANDS[b.type];if(!def)continue;const row=el('div','block-row '+def.color+'-block');row.draggable=true;row.tabIndex=0;row.setAttribute('aria-label',def.label+' '+b.value);row.append(el('span','',def.label));if(!['forever','scan'].includes(b.type)){const inp=el('input');inp.type='number';inp.value=b.value;inp.setAttribute('aria-label','Valor de '+def.label);inp.oninput=()=>{b.value=Number(inp.value);updateJavaPeek();save();};row.append(inp,el('span','',def.unit));}const tools=el('span','block-tools');for(const [label,desc,fn] of [['↑','Subir bloque',()=>{if(i>0)[list[i-1],list[i]]=[list[i],list[i-1]];}],['↓','Bajar bloque',()=>{if(i<list.length-1)[list[i+1],list[i]]=[list[i],list[i+1]];}],['×','Eliminar bloque',()=>list.splice(i,1)]]){const btn=el('button','',label);btn.title=desc;btn.setAttribute('aria-label',desc);btn.onclick=ev=>{ev.stopPropagation();fn();insertPath=[];renderBlocks();save();};tools.append(btn);}row.append(tools);row.ondragstart=ev=>{ev.stopPropagation();ev.dataTransfer.setData('application/otea-block',JSON.stringify({path,index:i}));};row.ondragover=ev=>{ev.preventDefault();ev.stopPropagation();};row.ondrop=ev=>{ev.preventDefault();ev.stopPropagation();const type=ev.dataTransfer.getData('text/plain');if(COMMANDS[type])list.splice(i,0,newBlock(type));else{try{const from=JSON.parse(ev.dataTransfer.getData('application/otea-block'));const fromList=listAt(from.path);if(fromList!==list)return toast('Para mover entre niveles, elimina y añade la pieza en su nuevo nivel.');const item=fromList.splice(from.index,1)[0];list.splice(i,0,item);}catch{}}renderBlocks();save();};if(['repeat','forever','ifEnergy'].includes(b.type)){const nest=el('div','block-children');render(b.children||[],nest,[...path,i]);const add=el('button','add-child','＋ Añadir aquí');add.onclick=ev=>{ev.stopPropagation();insertPath=[...path,i];toast('Las próximas piezas irán dentro de '+def.label+'.');};nest.append(add);row.append(nest);}parent.append(row);}};render(tank().blocks[eventKey],target,[]);target.ondragover=e=>e.preventDefault();target.ondrop=e=>{e.preventDefault();const type=e.dataTransfer.getData('text/plain');if(COMMANDS[type]){listAt(insertPath).push(newBlock(type));renderBlocks();save();}};if(!tank().blocks[eventKey].length)target.append(el('p','micro','Tu programa empieza aquí. Pulsa una pieza para añadirla.'));updateJavaPeek();}
function newBlock(type){const b={type,value:COMMANDS[type].value};if(['repeat','forever','ifEnergy'].includes(type))b.children=[];return b;}
function updateJavaPeek(){$('#java-preview').textContent=blocksJava(tank().blocks,tank().name,tank().color);renderJavaIdentity();}
function renderEditor(){renderList();const t=tank();$('#tank-name').value=t.name;$('#tank-creator').value=t.creator||'';$('#tank-part-color').value=tankColors(t)[$('#tank-part').value||'body'];$('#tank-color').value=t.color;$('#tank-skin').value=t.skin;$('#language').value=t.language==='blocks'?'java':t.language;$('#source').value=t.code;$('#blocks-editor').hidden=t.language!=='blocks';$('#code-editor').hidden=t.language==='blocks';$('#mode-blocks').classList.toggle('selected',t.language==='blocks');$('#mode-code').classList.toggle('selected',t.language!=='blocks');renderBlocks();updateCodeMeta();drawPreview();$('#mission-guide').hidden=!mission||mission.tankId!==t.id;}
function updateCodeMeta(){renderJavaIdentity();const lang=$('#language').value;$('#line-numbers').textContent=Array.from({length:$('#source').value.split('\n').length},(_,i)=>i+1).join('\n');$('#language-info').textContent=lang==='java'?'Java real, compilado con Eclipse ECJ y ejecutado en JVM Java 17. Usa la API original de robocode.Robot o AdvancedRobot.':lang==='python'?'Python real (CPython/Pyodide). Define async def run(robot) y espera cada orden con await. Motor Arena web.':'JavaScript real en un worker. Define async function run(robot), utiliza await y registra los eventos en robot. Motor Arena web.';}
function drawPreview(){const c=$('#preview').getContext('2d');c.clearRect(0,0,270,220);c.strokeStyle='#ffb34730';c.beginPath();c.ellipse(135,150,95,30,0,0,Math.PI*2);c.stroke();drawTank(c,135,105,30,45,tank().color,tank().skin,1.8,true,tankColors(tank()));const a=$('#anatomy').getContext('2d');a.clearRect(0,0,260,190);drawTank(a,116,110,0,25,tank().color,tank().skin,1.4,true,tankColors(tank()));a.font='11px monospace';a.fillStyle='#9ddbff';a.fillText('CUERPO',15,155);a.fillStyle='#fb799a';a.fillText('CAÑÓN',173,70);a.fillStyle='#80f5d0';a.fillText('RADAR',175,124);a.strokeStyle='#80f5d0';a.beginPath();a.moveTo(131,108);a.lineTo(170,120);a.stroke();}
$('#block-event').replaceChildren(...Object.entries(EVENTS).map(([key,d])=>{const o=el('option','',d.label);o.value=key;return o;}));
for(const [type,d] of Object.entries(COMMANDS)){const b=el('button','palette-block '+d.color+'-block',d.label);b.draggable=true;b.ondragstart=e=>e.dataTransfer.setData('text/plain',type);b.onclick=()=>{if(listAt(insertPath).length>=100)return toast('Máximo 100 piezas en este nivel.');listAt(insertPath).push(newBlock(type));renderBlocks();save();};$('#palette').append(b);}
