function participantList(container,engine,selectedIds){container.replaceChildren();for(const t of project.tanks){const compatible=engine==='jvm'?['java','blocks'].includes(t.language):t.language!=='java';const label=el('label','participant');const input=el('input');input.type='checkbox';input.value=t.id;input.disabled=!compatible;input.checked=compatible&&(selectedIds?selectedIds.includes(t.id):true);const caption=el('span','participant-caption');caption.append(el('span','',t.name));if(engine==='jvm'&&compatible){const identity=javaIdentity(t);caption.append(el('code','participant-java',identity?.fullName||'Clase Java sin reconocer'));}label.append(input,caption,el('small','',t.language));container.append(label);}container.onchange=()=>renderJavaSelection(container,engine);renderJavaSelection(container,engine);}
function renderParticipants(){const ids=[...$('#participants').querySelectorAll('input:checked')].map(n=>n.value);participantList($('#participants'),$('#engine').value,ids.length?ids:undefined);$('#engine-info').textContent=$('#engine').value==='jvm'?'JVM Java 17 + Robocode 1.11.1. Java completo y bloques exportados a Java. Campo libre, posiciones aleatorias originales. La semilla web y los obstáculos no modifican el motor clásico.':'Bloques, CPython y JavaScript ejecutados en tu navegador. Obstáculos, semilla reproducible y telemetría educativa.';$('#map-select').disabled=$('#engine').value==='jvm';$('#seed').disabled=$('#engine').value==='jvm';$('#map-editor-toggle').disabled=$('#engine').value==='jvm';if(spectating)for(const id of ['engine','ticks','seed','cooling','map-select','theme','random-seed','map-editor-toggle'])$('#'+id).disabled=true;}
function renderTournamentParticipants(){const engine=$('#tournament-engine').value;participantList($('#tournament-participants'),engine,project.uiState?.tournament);if(!roomState){$('#tournament-map').disabled=engine==='jvm';if(engine==='jvm')$('#tournament-map').value='classic';}}
function selectedTanks(selector){return [...$(selector).querySelectorAll('input:checked')].map(i=>project.tanks.find(t=>t.id===i.value)).filter(Boolean).slice(0,9);}
function numeric(selector,min,max){const n=Number($(selector).value);if(!Number.isFinite(n)||n<min||n>max)throw Error('Revisa '+$(selector).closest('label')?.textContent.trim()+': entre '+min+' y '+max+'.');return n;}
function currentMap(){const name=$('#map-select').value;return name==='custom'?project.map:mapPreset(name);}
function log(message){$('#battle-log').textContent=(message+'\n'+$('#battle-log').textContent).slice(0,4000);}
