function showSingleStandings(tanks,result,name){standings=tanks.map((t,id)=>({id,name:t.name,creator:t.creator||'',points:result.cancelled?0:result.draw?1:result.winner===id?3:0,wins:!result.draw&&result.winner===id?1:0,draws:result.draw&&!result.cancelled?1:0,losses:!result.draw&&result.winner!==id?1:0,buchholz:0,combat:Math.round(result.scores?.find(s=>s.id===id)?.score||0),opponents:[]}));fixtures=[{a:tanks.map(t=>t.name).join(' · '),b:'batalla conjunta',result:result.cancelled?'Detenida':result.draw?'Empate':(tanks[result.winner]?.name||result.winnerName||'Carro de combate')+' gana',round:'Una partida · '+(result.ticks||lastState?.tick||0)+' turnos'}];currentTournament={name,engine:battleEngine,pairing:'melee'};$('#league-title').textContent=name;standingsRender();}
async function startSingle(tanks,c,name){for(const t of tanks){validateTank(t);if(t.language==='blocks')validateBlocks(t.blocks);}if(tournamentRunning||running||jvmStarting)throw Error('Detén la partida actual antes de iniciar otra batalla.');mission=null;$('#mission-live').textContent='';$('#theme').value=c.theme;$('#map-select').value=c.map;$('#engine').value=c.engine;go('arena');renderParticipants();const result=await runBattle(tanks,c.engine,{seed:c.seed,maxTicks:c.maxTicks,map:c.engine==='jvm'?[]:mapPreset(c.map),cooling:Number($('#cooling').value)||.1});showSingleStandings(tanks,result,name);$('#tournament-status').textContent=result.cancelled?'Batalla detenida.':'BATALLA CONJUNTA COMPLETADA · '+tanks.length+' participantes';return result;}
async function startRoomBattle(){if(roomBusy||!roomState?.host||roomState.status!=='waiting')return;roomBusy=true;try{await roomConfigChain;if(roomConfigDirty){const updated=await room.action('config',{config:roomConfig()});roomConfigDirty=false;roomRender(updated);}if(running||jvmStarting||tournamentRunning)throw Error('Detén la partida actual antes de iniciar la sala.');const data=await room.action('start');const tanks=data.participants.map(p=>p.tank),members=data.participants.map(p=>p.id);for(const t of tanks){validateTank(t);if(t.language==='blocks')validateBlocks(t.blocks);}roomBattle=true;lastRoomPush=0;const result=await startSingle(tanks,data.config,data.name);roomBattle=false;if(lastState&&running===false)await room.action('frame',{frame:snapshotCopy(lastState)});const winning=tanks[result.winner];await room.action('result',{result:{...result,winnerTankId:winning?.id||null,winnerMemberId:members[result.winner]||null,winnerName:winning?.name||'',winnerCreator:winning?.creator||''}});}catch(e){roomBattle=false;if(roomState?.status==='running')try{await room.action('result',{result:{cancelled:true,draw:true,winner:null,scores:[]}});}catch{}throw e;}finally{roomBusy=false;}}
room=new RoomClient(roomRender,e=>{$('#room-status').textContent=e.message;if([401,410].includes(e.status))roomCleanup();});
function roomCleanup(){room.forget();roomState=null;roomResultSeen=null;roomConfigDirty=false;roomConfigRevision++;spectating=false;$('#room-live').hidden=true;for(const id of ['room-create','room-join','room-name','room-password','start-battle','pause-battle','step-battle','stop-battle','test-tank','simple-tournament','start-tournament','tournament-engine','tournament-map','tournament-theme','simple-ticks','room-auto','engine','ticks','seed','cooling','map-select','theme','random-seed','map-editor-toggle'])$('#'+id).disabled=false;renderTournamentParticipants();renderParticipants();$('#room-status').textContent='Has salido de la sala.';}
for(const [id,action] of [['room-create','create'],['room-join','join']])$('#'+id).onclick=guard(async()=>{if(running||jvmStarting||tournamentRunning)throw Error('Detén la partida actual antes de entrar en una sala.');const password=$('#room-password').value;try{await room.enter(action,$('#room-name').value,password,roomConfig());}finally{$('#room-password').value='';}});
$('#room-submit').onclick=guard(async()=>{const t=project.tanks.find(t=>t.id===$('#room-tank').value);if(!t)throw Error('Construye un carro de combate compatible primero.');validateTank(t);if(t.language==='blocks')validateBlocks(t.blocks);await room.action('submit',{tank:{...t,creator:t.creator||''}});toast('Carro de combate inscrito en la sala.');});
$('#room-add-bots').onclick=guard(async()=>{const list=selectedTanks('#tournament-participants');if(!list.length)throw Error('Selecciona los robots del hangar que quieres añadir.');for(const t of list){validateTank(t);if(t.language==='blocks')validateBlocks(t.blocks);}if(roomState.participants.length+list.length>8)throw Error('La sala admite ocho carros de combate en total.');roomBusy=true;try{for(const t of list)await room.action('submit',{tank:{...t,creator:t.creator||''},automatic:true});}finally{roomBusy=false;roomRender(roomState);}});
$('#room-start').onclick=guard(startRoomBattle);$('#room-stop').onclick=guard(async()=>{if(roomBattle){stop();}else await room.action('result',{result:{cancelled:true,draw:true,winner:null,scores:[]}});});$('#room-watch').onclick=()=>go('arena');$('#room-reset').onclick=guard(()=>room.action('reset'));
$('#room-leave').onclick=guard(async()=>{if(roomState?.host){if(roomBusy)throw Error('Detén la batalla antes de cerrar la sala.');await room.action('close');}else await room.action('leave');roomCleanup();});
$('#simple-tournament').onclick=guard(()=>{if(room?.session)throw Error('En una sala usa INICIAR BATALLA DE SALA.');return startSingle(selectedTanks('#tournament-participants'),roomConfig(),$('#tournament-name').value||'Copa OTEA');});
for(const id of ['tournament-engine','tournament-map','tournament-theme','simple-ticks','room-auto']){
 $('#'+id).addEventListener('input',()=>{if(room?.session&&roomState?.host)roomConfigDirty=true;});
 $('#'+id).addEventListener('change',guard(async()=>{if(id==='tournament-engine'){$('#tournament-map').disabled=$('#'+id).value==='jvm';if($('#'+id).value==='jvm')$('#tournament-map').value='classic';}if(room?.session&&roomState?.host){roomConfigDirty=true;const revision=++roomConfigRevision,c=roomConfig();roomConfigChain=roomConfigChain.catch(()=>{}).then(async()=>{const data=await room.action('config',{config:c});if(revision===roomConfigRevision){roomConfigDirty=false;roomRender(data);}});await roomConfigChain;}}));
}
