const settingsTabs=[...document.querySelectorAll('[data-settings-panel]')];
function settingsPanel(tab){for(const item of settingsTabs){const active=item===tab;item.setAttribute('aria-selected',String(active));item.tabIndex=active?0:-1;$('#settings-panel-'+item.dataset.settingsPanel).hidden=!active;}}
for(const [index,tab] of settingsTabs.entries()){tab.onclick=()=>settingsPanel(tab);tab.onkeydown=e=>{if(!['ArrowRight','ArrowLeft','ArrowDown','ArrowUp','Home','End'].includes(e.key))return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?settingsTabs.length-1:(index+(['ArrowRight','ArrowDown'].includes(e.key)?1:settingsTabs.length-1))%settingsTabs.length;settingsPanel(settingsTabs[next]);settingsTabs[next].focus();};}
$('#settings-done').onclick=()=>$('#settings').close();
