$('#mission-track').onchange=renderMissions;$('#next-mission').onclick=()=>startMission(MISSIONS.find(m=>!project.completed.includes(m.id))||daily());$('#export-progress').onclick=()=>download('RoboCODEx-ficha-de-practica.html',progressReport(project,MISSIONS),'text/html;charset=utf-8');$('#mission-exit').onclick=()=>{stop();mission=null;missionAttempt=null;$('#mission-guide').hidden=true;$('#mission-live').textContent='';diagnostics('Entrenamiento cerrado. Tu código y progreso se conservan.');};
